package com.jaymospowers.alchemy.hunter;

import net.minecraft.world.item.Item;
import org.jspecify.annotations.Nullable;

/**
 * Every hunter's brew (Hunter's Road, patch 6, "D2" and "D3"): the eight draughts and the cleanser, each in three grades
 * ({@link Draughts#tier}), and the six monster brews, each made from the organ of one monster ({@link #organ}).
 * Its crucible recipes, essences and formula are data (generated by {@code tools/gen_hr6b_data.py}); what it does is in
 * {@link Draughts}.
 */
public enum Draught {
	SLOW_MENDING("slow_mending", null), GREY_SIGHT("grey_sight", null), SAVAGERY("savagery", null), KEEN_EDGE("keen_edge", null),
	DEEP_BREATH("deep_breath", null), THORNED_BLOOD("thorned_blood", null), THIN_VENOM("thin_venom", null), PLENTY("plenty", null),
	CLEANSER("cleanser", null),
	/** More harm while at full health (a mire hag's gall). */
	MARSH_FURY("marsh_fury", "jaymoskitchen:mire_gall"),
	/** Healing for each kill in a row (a grave hag's tongue). */
	GRAVE_HUNGER("grave_hunger", "jaymoskitchen:grave_tongue"),
	/** Fed while untouched (a gnawer leader's marrow). */
	PACK_MARROW("pack_marrow", "jaymoskitchen:pack_marrow"),
	/** Half the harm in rain (a fog-wight's sac). */
	FOG_SHROUD("fog_shroud", "jaymoskitchen:wight_sac"),
	/** A faster mount (a warrior imp's gizzard). */
	IMP_GALLOP("imp_gallop", "jaymoskitchen:imp_gizzard"),
	/** A troll's healing (a troll's liver). */
	TROLL_BLOOD("troll_blood", "jaymoskitchen:troll_liver");

	public final String id;
	/** The organ item id a monster brew is made from, or null for a draught. */
	public final @Nullable String organ;
	/** Set when the item is registered. */
	public Item item;

	Draught(String id, @Nullable String organ) {
		this.id = id;
		this.organ = organ;
	}

	public boolean monster() {
		return organ != null;
	}

	/** Draughts go through the Brewer's Alembic for a grade better; a monster brew has no grades. */
	public boolean distillable() {
		return organ == null;
	}

	/** The item's id: {@code draught_<id>} or {@code brew_<id>}. */
	public String itemId() {
		return (monster() ? "brew_" : "draught_") + id;
	}

	/** The research (Codex formula) id that lets the crucible make it. */
	public String formulaId() {
		return "formula_" + id;
	}

	public static @Nullable Draught byId(String id) {
		for (Draught d : values()) {
			if (d.id.equals(id)) {
				return d;
			}
		}
		return null;
	}
}
